const raw = $input.first().json.output || '';
let o;
try { o = JSON.parse(raw.replace(/```json|```/g, '').trim()); } catch (e) { o = { intent: 'chat', reply: raw }; }
const ex = $('Extract Message').first().json;
return [{ json: {
  intent: String(o.intent || 'chat').toLowerCase(),
  reply: o.reply || '',
  slot_id: o.slot_id || '',
  new_slot_id: o.new_slot_id || '',
  patient_name: o.patient_name || ex.name || '',
  doctor_name: o.doctor_name || '',
  date: o.date || '',
  time: o.time || '',
  queue_number: o.queue_number || '',
  "from":"201159016725"
} }];

const TZ = 'Africa/Cairo';
const HORIZON_DAYS = 14;
const DEFAULT_MINUTES = 20;

const events = $('Get Calendar Events').all().map(i => i.json).filter(e => e && e.start && e.start.dateTime);
const doctors = $('Get Doctors').all().map(i => i.json).filter(d => d && d.doctor_id);
const slots = $('Get Existing Slots').all().map(i => i.json).filter(s => s && s.slot_id);

const docMap = {};
for (const d of doctors) docMap[String(d.doctor_id).trim().toUpperCase()] = d;

const existing = new Set(slots.map(s => String(s.slot_id).trim()));
const queue = {}; // doctor|date -> last queue number
for (const s of slots) {
  const k = `${s.doctor_id}|${s.date}`;
  queue[k] = Math.max(queue[k] || 0, parseInt(s.queue_number) || 0);
}

const now = DateTime.now().setZone(TZ);
const limit = now.plus({ days: HORIZON_DAYS }).endOf('day');
const out = [];
const unknown = new Set();

events.sort((a, b) => a.start.dateTime.localeCompare(b.start.dateTime));

for (const e of events) {
  const docId = String(e.summary || '').trim().split(/[\s|\-–:]+/)[0].toUpperCase();
  const doc = docMap[docId];
  if (!doc) { unknown.add(e.summary); continue; }

  let mins = parseInt(doc.slot_minutes) || DEFAULT_MINUTES;
  const m = String(e.description || '').match(/slot\s*=\s*(\d+)/i);
  if (m) mins = parseInt(m[1]);

  const start = DateTime.fromISO(e.start.dateTime, { zone: TZ });
  const end = DateTime.fromISO(e.end.dateTime, { zone: TZ });

  let t = start;
  while (t.plus({ minutes: mins }) <= end) {
    if (t > now && t <= limit) {
      const date = t.toFormat('yyyy-MM-dd');
      const time = t.toFormat('HH:mm');
      const slot_id = `${doc.doctor_id}-${t.toFormat('yyyyMMdd-HHmm')}`;
      if (!existing.has(slot_id)) {
        const k = `${doc.doctor_id}|${date}`;
        queue[k] = (queue[k] || 0) + 1;
        existing.add(slot_id);
        out.push({ json: {
          slot_id,
          doctor_id: doc.doctor_id,
          doctor_name: doc.doctor_name || doc.name || '',
          specialty: doc.specialty || '',
          date,
          time,
          queue_number: queue[k],
          status: 'available',
          patient_phone: '',
          patient_name: '',
          source: '',
          booked_at: ''
        }});
      }
    }
    t = t.plus({ minutes: mins });
  }
}

if (unknown.size) console.log('Calendar events with unknown doctor_id:', [...unknown].join(' | '));
return out;
